#!/usr/bin/env python3
"""Deepen the Zhengde era through finance, frontier armies, court access and succession."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "App/Resources/history.json"
NARRATION = ROOT / "App/Resources/narration_manifest.json"


def upsert(items: list[dict], item: dict, key: str = "id") -> None:
    for index, old in enumerate(items):
        if old.get(key) == item[key]:
            items[index] = item
            return
    items.append(item)


def section(sid: str, title: str, text: str, sources: list[str], events: list[str], people: list[str]) -> dict:
    return {
        "id": sid,
        "title": title,
        "text": text,
        "kind": "史实与解读",
        "sources": sources,
        "events": events,
        "people": people,
    }


def article(person: str, title: str, dek: str, sections: list[dict]) -> dict:
    sources: list[str] = []
    for item in sections:
        for source in item["sources"]:
            if source not in sources:
                sources.append(source)
    return {"person": person, "title": title, "dek": dek, "sections": sections, "sources": sources}


def upsert_association(data: dict, item: dict) -> None:
    for index, old in enumerate(data["associations"]):
        if old["from"] == item["from"] and old["to"] == item["to"]:
            data["associations"][index] = item
            return
    data["associations"].append(item)


def main() -> None:
    data = json.loads(DATA.read_text(encoding="utf-8"))

    sources = [
        {"id": "v143_ms186", "title": "《明史》卷186 · 韩文传", "url": "https://zh.wikisource.org/zh-hans/明史/卷186", "note": "清修正史开放转录，用于核对韩文赈粮、户部国计、盐法与皇庄争议，以及正德初九卿伏阙。列传以忠直大臣为叙事框架；奏疏数字、宫廷反应与道德评价仍需和本纪、食货志互证。"},
        {"id": "v143_ms190", "title": "《明史》卷190 · 杨廷和传", "url": "https://zh.wikisource.org/zh-hans/明史/卷190", "note": "清修正史开放转录，用于核对杨廷和入阁、正德巡幸期间居守、武宗去世后的继承安排、裁撤边兵和正德末清理。列传带有首辅中心视角，诏书裁减数字不能直接等同于全部执行结果。"},
        {"id": "v143_ms198", "title": "《明史》卷198 · 杨一清传", "url": "https://zh.wikisource.org/zh-hans/明史/卷198", "note": "清修正史开放转录，用于核对杨一清的茶马、边墙、三边总制、安化王事变和与张永揭发刘瑾。传记突出谋略和知兵，边墙尺度、战果与君臣对话仍是官修叙事口径。"},
        {"id": "v143_ms304", "title": "《明史》卷304 · 刘瑾、张永传", "url": "https://zh.wikisource.org/zh-hans/明史/卷304", "note": "清修正史开放转录，用于核对刘瑾变法与迫害、张永参与安化王善后和揭发刘瑾、江西军功争议。宦官传以善恶褒贬组织材料，查抄数量、密谈和案情细节不作现代财富排名。"},
        {"id": "v143_ms307", "title": "《明史》卷307 · 钱宁、江彬传", "url": "https://zh.wikisource.org/zh-hans/明史/卷307", "note": "清修正史开放转录，用于核对钱宁掌锦衣卫、江彬引边军入京、武宗巡幸和身后处置。佞幸传具有强烈道德框架，暴力、查抄与宫廷逸事需与本纪互证，不能把戏剧性细节都当作逐字实录。"},
        {"id": "v143_ms117", "title": "《明史》卷117 · 宁王朱宸濠传", "url": "https://zh.wikisource.org/zh-hans/明史/卷117", "note": "清修正史开放转录，用于核对宁府恢复护卫、收夺田产、京中行贿、孙燧上报受阻及1519年起兵和平定。兵力、伤亡和四十三日等数字来自官修叛乱叙事，需区分动员号称、实际参战与后世汇总。"},
    ]
    for source_item in sources:
        upsert(data["sources"], source_item)

    people = [
        {"id": "m143_hanwen", "name": "韩文", "call": "以户部账目追问宫廷开支、盐法与皇庄成本的正德初重臣", "temple": "—", "era": "成化—正德", "reign": "1441—1526", "summary": "历任地方和户部官，赈济南京灾荒，反对残盐请引、皇庄扰民与无节制赏赉；正德初率九卿伏阙要求处置近侍，失败后遭刘瑾打击。", "parent": None, "sources": ["v143_ms186", "v2l_ms16", "v143_ms304"], "kind": "户部与国计大臣", "note": "字贯道，山西洪洞人。列传以忠直塑造其形象；户部奏数与传记中的哭泣、对话须区分账册证据和文学化叙述。", "dynasty": "ming"},
        {"id": "m143_yangtinghe", "name": "杨廷和", "call": "在皇帝长期离京与无嗣身后维持中枢、安排继承的正德首辅", "temple": "—", "era": "成化—嘉靖", "reign": "1459—1529", "summary": "由东宫讲官进入内阁，正德中多次反对巡幸而未能阻止；武宗南征时居守，去世后与张太后及阁臣确定兴王世子继位，并主持裁撤正德末特殊编制。", "parent": None, "sources": ["v143_ms190", "v2l_ms16", "v143_ms307"], "kind": "内阁与继承秩序", "note": "字介夫，四川新都人。其正德末处置是理解嘉靖初政的关键，但《明史》明显肯定其镇静与清弊，实际裁撤执行需另看部册。", "dynasty": "ming"},
        {"id": "m143_yangyiqing", "name": "杨一清", "call": "把茶马、边墙、三边指挥与中枢权力变化连起来的边政大臣", "temple": "—", "era": "成化—嘉靖", "reign": "1454—1530", "summary": "长期经营陕西茶马与边防，提出三边统一指挥和修墙设堡；遭刘瑾构陷后复起处理安化王事变，并推动张永揭发刘瑾，后来又受钱宁、江彬排挤。", "parent": None, "sources": ["v143_ms198", "v143_ms304", "v2l_ms16"], "kind": "三边总制与中枢大臣", "note": "字应宁，祖籍云南安宁，后居丹徒。边墙计划和政治谋划常被写成个人远见，必须补入军费、征役、部将与地方协作。", "dynasty": "ming"},
        {"id": "m143_zhangyong", "name": "张永", "call": "由武宗近侍转为刘瑾案、江西善后与正德末权力转换中的宦官", "temple": "—", "era": "正德—嘉靖", "reign": "？—1529", "summary": "原属武宗旧侍集团，先与刘瑾合作，后因冲突在安化王事变后揭发刘瑾；南征期间接收朱宸濠并约束部分近侍，武宗死后又参与九门防变和拘捕江彬。", "parent": None, "sources": ["v143_ms304", "v143_ms190", "v143_ms117"], "kind": "司礼近侍与军事监军", "note": "保定新城人，生年不详。不能因后来反刘瑾就抹去其早期近侍身份，也不能把《明史》为其辨诬直接当作全部地方经验。", "dynasty": "ming"},
        {"id": "m143_qianning", "name": "钱宁", "call": "以锦衣卫、诏狱和私人进献控制接近皇帝渠道的正德近幸", "temple": "—", "era": "正德", "reign": "？—1521", "summary": "由宦官家奴进入锦衣卫，刘瑾死后掌南镇抚司与锦衣卫，以义子身份接近武宗；又为宁王恢复护卫和进献提供京中渠道，宁王起兵后失势。", "parent": None, "sources": ["v143_ms307", "v143_ms117", "v2l_ms16"], "kind": "锦衣卫近幸", "note": "出身地点、生年均不确定。佞幸传的秘戏、财富和亲昵细节有强烈道德化色彩，可靠重点是职位、案件和可核对的政治关系。", "dynasty": "ming"},
        {"id": "m143_jiangbin", "name": "江彬", "call": "把边军、豹房、巡幸和厂卫权力汇合到皇帝身边的正德武臣", "temple": "—", "era": "正德", "reign": "？—1521", "summary": "由宣府卫官参与镇压北直隶起事，因战伤和骑射获得武宗信任；主张调四镇边军入京，推动宣府巡幸和南征，武宗死后在张太后、杨廷和等安排下被捕。", "parent": None, "sources": ["v143_ms307", "v143_ms190", "v2l_ms16"], "kind": "边军近幸与团营统领", "note": "宣府人，生年不详。其暴力和巡幸责任有明确史料基础，但不能用佞幸传的每项逸事代替军队编制、供给和皇帝最终授权。", "dynasty": "ming"},
        {"id": "m143_zhuchenhao", "name": "朱宸濠", "call": "借护卫、田产和京中关系扩张权力，最终在江西起兵的宁王", "temple": "—", "era": "弘治—正德", "reign": "？—1521", "summary": "宁献王朱权后裔，正德年间通过钱宁等恢复部分护卫并扩张王府田产；1519年在南昌扣押地方官、杀孙燧与许逵后起兵，四十余日内被王守仁组织地方兵力击败。", "parent": None, "sources": ["v143_ms117", "v143_ms307", "v40m2_ms195"], "kind": "宁藩宗室与叛乱首领", "note": "不能与明初宁王朱权混同。起兵兵力与伤亡数字出自平叛叙事；护卫恢复、田产纠纷和上报受阻比单一的个人野心更能解释风险积累。", "dynasty": "ming"},
    ]
    for person in people:
        upsert(data["people"], person)

    events = [
        {"id": "v143_nanjing_grain_relief", "year": "1504年前后", "sortYear": 1504, "title": "南京粮价上涨时先发军粮平粜赈济", "category": "社会", "body": "韩文任南京兵部尚书时遇歉收和米价上涨，主张预发三个月军饷粮，先开仓十六万石。做法同时保障军户并向市场增加粮源，反映灾荒应对不能等到常规文书全部完成。", "impact": "十六万石是列传中的官府发放规模，不是逐户收讫清册。先发粮可压低短期价格，也会减少仓储安全边际，必须配合后续补仓、运输和对最贫困家庭的直接救济。", "people": ["m143_hanwen"], "sources": ["v143_ms186"], "kind": "城市粮食与赈济"},
        {"id": "v143_zhengde_budget", "year": "1505—1506年", "sortYear": 1505, "title": "登极、山陵与大婚开支逼出内库和户部之争", "category": "经济", "body": "武宗即位后，赏赉、孝宗山陵和大婚等费用集中发生，韩文称所需银超过户部现存能力，建议内库出银、削减不急开支，并清理监局冗员和不透明积存。", "impact": "户部和内库不是现代意义上完全分离的公共与私人账户，但谁掌握金银、谁承担支出会改变责任。传记中的总额是奏疏口径，不能据此推算今日币值或断言国库已经枯竭。", "people": ["houzhao", "m143_hanwen"], "sources": ["v143_ms186", "v2l_ms16"], "kind": "宫廷财政"},
        {"id": "v143_estate_tenants", "year": "1505—1506年", "sortYear": 1506, "title": "皇庄管庄人员缩减，但佃户负担并未自动消失", "category": "经济", "body": "韩文等针对霸州等地皇庄提出由巡抚召民承佃、按亩纳银并撤减中官与校尉，试图把王府和宫廷庄田纳入较可核查的地方征收。武宗最终只部分缩减管理人员。", "impact": "撤人不等于退还土地，也不保证租额合理；佃户仍可能面对正税、庄租和差役叠加。皇庄改革应区分土地权属、收租方式与基层执行，不能用一次诏令概括结果。", "people": ["houzhao", "m143_hanwen"], "sources": ["v143_ms186", "v2l_ms16"], "kind": "庄田与佃户"},
        {"id": "v143_nine_ministers_remonstrance", "year": "1506年", "sortYear": 1506, "title": "韩文率九卿伏阙，近侍集团反而控制要职", "category": "政治", "body": "韩文与九卿、科道官要求处置武宗东宫旧侍，刘健、谢迁等内阁大臣拒绝压下奏章。近侍连夜向皇帝申诉后，王岳被捕，刘瑾掌司礼监，刘健、谢迁去职，政治格局迅速逆转。", "impact": "这不是文官与宦官两个整齐集团的单线冲突：张永后来反刘瑾，李东阳选择留任。伏阙失败显示皇帝控制最终任免，也显示缺少稳定程序时，接近皇帝的渠道可以压过正式奏议。", "people": ["houzhao", "m143_hanwen", "m40_liujin", "m40_liujian", "m40_xieqian", "m143_zhangyong"], "sources": ["v143_ms186", "v143_ms304", "v2l_ms16"], "kind": "中枢权力转换"},
        {"id": "v143_teahorse_frontier_wall", "year": "1502—1507年", "sortYear": 1506, "title": "茶马、边墙和三边总制被放进同一套边防方案", "category": "军事", "body": "杨一清整顿陕西茶马，修筑平虏等城堡，并主张延绥、宁夏、甘肃由一名大臣统一协调。他提出增设墩台、城墙与守军，以减少敌军深入后仓促征援。", "impact": "边墙不是一条一次完工的封闭线，而是堡寨、墩台、道路和驻军的组合。列传保存的里数和预算属于规划与阶段施工口径；刘瑾介入后工程中止，不能把方案全文当成已建成事实。", "people": ["m143_yangyiqing", "m142_liudaxia"], "sources": ["v143_ms198", "v142_ms80"], "kind": "西北边防"},
        {"id": "v143_anhua_liujin", "year": "1510年", "sortYear": 1510, "title": "安化王事变成为张永揭发刘瑾的政治窗口", "category": "政治", "body": "宁夏安化王朱寘鐇起兵后很快被仇钺擒获。朝廷派杨一清与张永善后，二人利用献俘接近皇帝的机会揭发刘瑾。武宗查抄刘瑾家产并将其处死，随后撤改一批刘瑾时期制度。", "impact": "起兵檄文指斥刘瑾不等于事变只由反宦官正义驱动；宗室、军镇和地方矛盾需分别分析。刘瑾倒台也不是近侍政治终结，钱宁、江彬随后填补了新的接近渠道。", "people": ["houzhao", "m40_liujin", "m143_yangyiqing", "m143_zhangyong"], "sources": ["v143_ms198", "v143_ms304", "v2l_ms16"], "kind": "宗室事变与权力重组"},
        {"id": "v143_uprising_mobilization", "year": "1511—1512年", "sortYear": 1511, "title": "刘六、刘七等武装跨省流动，朝廷调边军进入内地", "category": "社会", "body": "北直隶起事者向山东、河南、南直隶等地流动，地方卫所与京军难以迅速控制，朝廷遂调宣府、大同等边军入内地。战争、征发、追剿和交通中断共同影响沿途乡村。", "impact": "官修史常以盗贼概括参与者，无法说明每支队伍的社会来源；也不能把土地与赋役压力机械写成所有人的唯一动机。可以确认的是跨区动员改变了军队配置，并为江彬进入皇帝视野提供机会。", "people": ["houzhao", "m143_jiangbin", "m143_zhangyong"], "sources": ["v143_ms307", "v143_ms304", "v2l_ms16"], "kind": "地方社会与军事动员"},
        {"id": "v143_outer_four_armies", "year": "1512—1514年", "sortYear": 1513, "title": "四镇边军长期留京，形成外四家与威武营体系", "category": "军事", "body": "江彬以边军骁勇为由，推动辽东、宣府、大同、延绥军队调入北京，设置神威、敢勇等营，并把仓场改作驻军空间。武宗亲自检阅，江彬兼领四镇兵。", "impact": "精锐入京增强皇帝可直接调用的武力，也增加军饷、住宿和城市治安压力，并削弱原镇防守。佞幸传强调军士横行，具体规模与日常纪律仍需军籍互证；制度风险在于指挥链依附私人信任。", "people": ["houzhao", "m143_jiangbin", "m143_qianning"], "sources": ["v143_ms307", "v2l_ms16"], "kind": "京营与边军"},
        {"id": "v143_lecture_documents", "year": "1507—1517年", "sortYear": 1513, "title": "东宫讲读、会典编纂与诰敕工作进入正德中枢", "category": "文化", "body": "杨廷和早年为太子讲官并参与《明会典》《孝宗实录》等编纂，入阁后负责诰敕。讲筵和典章整理不是装饰：它们决定皇帝接触何种历史解释，也把机构职责和先例整理成可引用文本。", "impact": "熟悉掌故不能保证建议被采纳；武宗巡幸、边兵与宫市问题上，杨廷和多次进谏仍无效。知识生产能提供判断框架，却需要稳定的召对、奏议和执行渠道才能转化为治理。", "people": ["houzhao", "m143_yangtinghe"], "sources": ["v143_ms190", "v2l_ms16"], "kind": "讲筵与制度知识"},
        {"id": "v143_imperial_shops_tours", "year": "1514—1518年", "sortYear": 1517, "title": "皇店、宫市与巡幸把宫廷消费转成地方供给", "category": "经济", "body": "杨一清、杨廷和等反对皇店、宫市、江南织造和大批边兵宿卫；江彬推动武宗出居庸关、驻宣府和巡行北边。行在需要粮草、车马、住所与护卫，沿途还发生临时征取。", "impact": "巡边并非毫无军事信息价值，但皇帝出行的公共成本不能被个人勇武抵消。不同材料对掠取和逸乐细节带有道德化叙述，应把可核对的驻地、军队与诏令同戏剧性逸闻分开。", "people": ["houzhao", "m143_yangtinghe", "m143_yangyiqing", "m143_jiangbin"], "sources": ["v143_ms190", "v143_ms198", "v143_ms307", "v2l_ms16"], "kind": "巡幸供应链"},
        {"id": "v143_ning_prince_network", "year": "1507—1519年", "sortYear": 1518, "title": "宁王通过护卫、田产与京中进献逐步扩大行动空间", "category": "政治", "body": "朱宸濠请求恢复宁府护卫、夺取官民田产，并通过钱宁、臧贤等向武宗身边进献。巡抚孙燧多次上报风险受阻，直到1519年朝廷决定收回护卫和所夺田地时，宁王提前起兵。", "impact": "行贿网络解释警报为何迟迟未进入决策中心，但不能把所有官员都写成同谋。护卫、土地和继承期待相互强化，说明宗室风险不是某天突然产生，而是监督失灵长期累积。", "people": ["m143_zhuchenhao", "m143_qianning", "m143_jiangbin", "m40_wangshouren"], "sources": ["v143_ms117", "v143_ms307", "v143_ms190"], "kind": "宗室监督"},
        {"id": "v143_south_tour_remonstrance", "year": "1519年", "sortYear": 1519, "title": "百余名官员反对南巡，跪罚、下狱与廷杖造成死亡", "category": "政治", "body": "武宗准备南巡时，刑部、兵部及科道官员连续上疏，百余人伏阙反对。皇帝命人跪罚、下狱并廷杖，部分官员死亡；宁王起兵后，亲征命令最终使南行成行。", "impact": "进谏者并非只反对皇帝旅行，而是担心供给、边防、政务和人身安全。官修本纪与列传确认处罚及死亡，但个别人数需逐案核对；政治意义在于反对意见遭身体惩罚。", "people": ["houzhao", "m143_jiangbin", "m143_yangtinghe"], "sources": ["v2l_ms16", "v143_ms307", "v143_ms190"], "kind": "进谏与惩罚"},
        {"id": "v143_ning_rebellion_local_cost", "year": "1519年", "sortYear": 1519, "title": "宁王起兵四十余日，地方官民承担动员、围城与追查代价", "category": "军事", "body": "朱宸濠在南昌杀害拒绝合作的孙燧、许逵，控制地方官并沿江攻安庆。王守仁、伍文定等调集府县兵先取南昌，再在鄱阳湖一带击败宁王。", "impact": "快速平定不代表地方代价轻微：征兵、船只、火攻、逃亡与战后追查都影响居民。《明史》的十万兵和巨大死伤是叛乱与献俘叙事口径，不应直接当作精确统计。", "people": ["m143_zhuchenhao", "m40_wangshouren", "houzhao", "m143_zhangyong"], "sources": ["v143_ms117", "v40m2_ms195", "v143_ms304"], "kind": "江西战事与地方社会"},
        {"id": "v143_succession_cleanup", "year": "1521年", "sortYear": 1521, "title": "武宗无嗣，继承安排与正德特殊编制清理同步进行", "category": "政治", "body": "武宗去世后，杨廷和等依宗室伦序请张太后迎立兴王世子朱厚熜；同时遣返入卫边军、停止威武营和不急工程，罢皇店、豹房部分人员，并在拘捕江彬前控制城门。", "impact": "继承不是只宣读一个名字，还需控制军队、首都和信息。列传称裁汰近十五万人、减漕粮一百五十余万石，是诏令和汇总口径；不能据此断言所有人立即离岗或负担全部消失。", "people": ["houzhao", "houcong", "m143_yangtinghe", "m143_zhangyong", "m143_jiangbin"], "sources": ["v143_ms190", "v143_ms307", "v2l_ms16"], "kind": "皇位继承与制度收尾"},
    ]
    for event in events:
        upsert(data["events"], event)

    S186, S190, S198, S304, S307, S117, S16 = (
        "v143_ms186", "v143_ms190", "v143_ms198", "v143_ms304", "v143_ms307", "v143_ms117", "v2l_ms16"
    )
    readings = [
        article("m143_hanwen", "韩文：把宫廷开支还原成粮、银与佃户负担", "他反对的不只是刘瑾，而是一套让公共开支失去边界、让正额之外成本落到军民身上的运作方式。", [
            section("v143_hanwen_s1", "先发南京军粮，救荒也要承担仓储风险", "韩文在地方任职时就把财政看作居民能否活过灾年的问题。南京米价上涨，他要求预发军粮，户部担心程序与库存，他则愿意承担责任，最终开仓十六万石。列传把这一决定写成刚断，却没有逐户发放册和后续补仓记录。合理结论不是‘越过程序就是爱民’，而是灾害制度应预先授权地方在价格、人口和库存达到条件时先行处置，并留下运送、平粜与救济对象的复核链。", [S186], ["v143_nanjing_grain_relief"], []),
            section("v143_hanwen_s2", "登极、山陵和大婚为什么同时压向户部", "1505年前后，赏赉、孝宗山陵和武宗大婚集中发生。韩文认为户部现银不足，要求内库承担一部分，并削减不急费用、登记监局积存。内库与户部都服务皇权国家，却由不同人员掌握，开支被推给哪一方会改变谁能查账。传记所列一百八十余万两是奏疏口径，不能折算今日财富，也不能证明每项都已支付；它能说明礼仪与赏赐并非抽象盛典，而是具体的银、物料、工役和运输。", [S186, S16], ["v143_zhengde_budget"], ["houzhao"]),
            section("v143_hanwen_s3", "盐引和皇庄把边防财政带到佃户门前", "韩文反对外戚与商人用残盐请引获利，理由是盐法收入原本承担边储；他又要求缩减皇庄中官与校尉，改由地方召民承佃、按亩输银。两项争议共同指向财政链：特许盐引会改变商人、灶户与边镇资源，庄田管理会改变佃户在正税之外的租役。缩减管理者不等于土地返还，停止一批请引也不等于盐法恢复公平，仍需看执行与受益人。", [S186], ["v143_estate_tenants", "v142_salt_silver_reform"], ["m142_liudaxia"]),
            section("v143_hanwen_s4", "九卿伏阙为何反而加速权力逆转", "正德初，韩文与九卿、科道官要求处置武宗旧侍，刘健、谢迁也坚持奏章不能压下。近侍在皇帝身边连夜申诉后，支持外廷的王岳被捕，刘瑾掌司礼监，刘健、谢迁离职。韩文随后被列为奸党、削籍、罚米，家产受损。传记以忠奸冲突组织情节，但张永后来反刘瑾、李东阳留任，说明集团并非固定。关键问题是正式奏议没有稳定听取和复核程序，私人接近能在一夜间改写人事。", [S186, S304, S16], ["v143_nine_ministers_remonstrance"], ["m40_liujin", "m40_liujian", "m40_xieqian", "m143_zhangyong"]),
            section("v143_hanwen_s5", "刚直声望不能替代对账目和政策后果的复核", "刘瑾倒台后韩文恢复官职而不再任事，嘉靖初又获存问。后世常把他定格为哭谏与清廉，容易遮住其更重要的行政经验：救荒要知道仓粮，盐法要连接边储，庄田要观察佃户，宫廷开支要追问账户。与此同时，传记中的反对并非天然正确，例如预发军粮会减少储备、内库出银也可能缺少公开账册。评价韩文应逐项核对目标、成本、执行与受益者，而不是把个人品德当成政策效果。", [S186, S304], ["v143_nanjing_grain_relief", "v143_zhengde_budget"], ["m143_yangtinghe"]),
        ]),
        article("m143_yangtinghe", "杨廷和：皇帝离京以后，谁维持中枢并安排继承", "他的影响不在于每次进谏都成功，而在正德末的军事、城防、继承与裁撤必须被组织成同一场权力交接。", [
            section("v143_yangtinghe_s1", "从讲官与典章编纂进入内阁", "杨廷和早年参与《明会典》《孝宗实录》，又为太子讲官，熟悉诰敕、掌故、边事和民情。正德二年入阁后，他因讲筵言及近幸一度被调南京，数月后召回。知识与职位提供了发言资格，却没有自动生成执行力：讲筵能解释先例，皇帝仍可不听；典章能列明职掌，近侍仍可绕过官署。理解他的政治作用，应同时看文本知识和接近决策的实际渠道。", [S190, S16], ["v143_lecture_documents"], ["houzhao"]),
            section("v143_yangtinghe_s2", "巡幸期间的反对意见为何经常失效", "乾清宫灾后，杨廷和请早朝、日讲、还边兵、罢皇店、减织造；武宗长期在宣府等地时，他又请回銮，甚至到居庸关准备出塞进谏，仍被阻挡。列传称他未尝不谏，也承认不能裁禁近幸。这不是简单的软弱或忠勇二选一：内阁可以维持文书、提出理由，却缺少强迫皇帝回京的合法武力。反复无效的奏疏显示，信息上达和决策接受是两个不同环节。", [S190, S307, S16], ["v143_imperial_shops_tours"], ["m143_jiangbin", "m143_qianning"]),
            section("v143_yangtinghe_s3", "宁王已败，南征和居守仍继续消耗资源", "朱宸濠起兵后，杨廷和催促发布调兵命令，又反对武宗亲征。王守仁很快平乱，但皇帝仍南下，杨廷和与毛纪留守北京，两年间持续请求回銮。居守不是替皇帝统治全部地方，而是维持诏令、财政和首都安全，且须应对亲征名义下的军队与供给。列传赞其镇静，不能据此忽略地方已经承受的征发，也不能把王守仁的胜利算作内阁预先控制的结果。", [S190, S117, S16], ["v143_ning_rebellion_local_cost", "v143_south_tour_remonstrance"], ["m40_wangshouren", "m143_zhuchenhao"]),
            section("v143_yangtinghe_s4", "无嗣去世后的第一件事是同时控制名分与军队", "1521年武宗病重无嗣，杨廷和依据宗室伦序提出迎立兴王世子，并由张太后懿旨与遗诏确认。与此同时，入卫边军、威武营、城门和江彬集团仍在，继承不能只靠谱牒。杨廷和一面以温言稳住江彬，一面与司礼监人员请张太后下令拘捕。列传把决策集中到首辅，实际还包括太后、阁臣、宦官、守门军和宗室使者，任何一环失控都可能改变交接。", [S190, S307, S16], ["v143_succession_cleanup"], ["houcong", "m143_zhangyong", "m143_jiangbin"]),
            section("v143_yangtinghe_s5", "大规模裁撤是诏令起点，不是完成证明", "迎立决定后，朝廷遣返边军、罢威武营、皇店和部分豹房人员，停止不急工程，又称裁汰锦衣内监等近十五万人、减漕粮一百五十余万石。这些数字来自诏令与官修汇总，应理解为拟裁名额和账面负担，不能推定每人立即离岗、每石粮都到达减负对象。正德收尾给嘉靖初政带来声望，也把‘新政’与首辅个人绑定；随后大礼议冲突说明，成功交接并未解决皇帝和内阁对宗法权威的根本分歧。", [S190, S16], ["v143_succession_cleanup"], ["houcong", "m143_hanwen"]),
        ]),
        article("m143_yangyiqing", "杨一清：边墙、茶马与一次改变中枢格局的献俘", "他的经历说明边政不是只修墙，中枢政治也不是只靠奏章；工程、马匹、军粮、监军和皇帝信任彼此相连。", [
            section("v143_yangyiqing_s1", "陕西茶马不是一项孤立的贸易", "杨一清督理陕西马政时整顿私茶，希望用官茶换取番马供军。茶对西北部众是日常消费和交易品，对明朝则是获取军马、维系关系的政策工具。禁止私茶能增加官府控制，也可能压缩沿边居民合法生计并抬高价格。列传以番马大集衡量成效，没有保存所有交易者成本。茶马政策必须与互市、羁縻、军马养护和地方市场一起阅读，不能只当作廉政故事。", [S198, "v142_ms80"], ["v143_teahorse_frontier_wall"], ["m142_liudaxia"]),
            section("v143_yangyiqing_s2", "三边总制和修墙解决的是协同迟缓", "延绥、宁夏、甘肃遇警时各自征援容易迟到，杨一清主张由大臣统一协调，并提出城堡、墙堑、墩台、守军和道路的组合方案。边墙并非连续石城，而是依地形配置的防御网络，也需要长期修缮、粮饷与驻军家庭。列传所列数百里和九百墩台属于规划尺度，刘瑾介入后实际只完成部分。评价不能把未完计划绘成既成疆界，也不能忽略征夫和帑金成本。", [S198, S16], ["v143_teahorse_frontier_wall"], ["m142_liudaxia", "m42_mawensheng"]),
            section("v143_yangyiqing_s3", "安化王善后怎样变成揭发刘瑾的机会", "1510年安化王起兵很快被仇钺擒获，杨一清与张永奉命善后。杨一清判断张永能在献俘时直接接近皇帝，劝其揭发刘瑾；张永提前入京，武宗随后查抄并处死刘瑾。《明史》用画掌写‘瑾’等细节突出智谋，不宜当作逐字实录。可以确认的是，正式言官此前难以撼动刘瑾，必须借军事成功、近侍身份与皇帝信任重组，才打开撤权窗口。", [S198, S304, S16], ["v143_anhua_liujin"], ["m143_zhangyong", "m40_liujin"]),
            section("v143_yangyiqing_s4", "刘瑾倒台后，边政与中枢并未恢复单一秩序", "杨一清复官后甄录部分受刘瑾打击者，处理盗乱和边务，并进入内阁。他同时批评皇店、织造、宫中宿边兵等问题。张永失势、钱宁和江彬得宠后，他的奏疏触怒新近幸，又因私人指控离职。这一过程说明清除一名权宦不能消除依附皇帝私人信任的人事渠道；所谓恢复旧制也并非回到无冲突状态，官员推荐、部院职责和近侍关系继续竞争。", [S198, S307], ["v143_outer_four_armies", "v143_imperial_shops_tours"], ["m143_qianning", "m143_jiangbin"]),
            section("v143_yangyiqing_s5", "能臣评价必须容纳未完成工程与政治联盟", "杨一清通晓边事，也善于结交人才和近侍。他与张永合作推动刘瑾倒台具有公共后果，但合作本身仍是宫廷权力运作；其修墙方案有明确军事逻辑，也需要高额资金和劳役；他后来入阁与再次总制三边，又卷入嘉靖政治。官修传记常把预见成败归于一人，阅读时应把部将、边民、茶商、工役和其他大臣重新写回因果链。承认个人能力，不等于让能力叙事吞掉执行成本。", [S198, S304], ["v143_teahorse_frontier_wall", "v143_anhua_liujin"], ["m143_zhangyong", "m143_yangtinghe"]),
        ]),
        article("m143_zhangyong", "张永：近侍集团内部并非一成不变", "他曾与刘瑾同属武宗旧侍，也参与刘瑾倒台、江西善后和正德末城防；阶段变化比简单的忠奸标签更重要。", [
            section("v143_zhangyong_s1", "最初的权力来自同一位太子旧侍", "张永正德初掌神机营，与刘瑾同在武宗近侍集团。两人并非从一开始就是正邪对手；张永因分权与刘瑾冲突，甚至在皇帝面前相殴，才逐渐分裂。近侍能够控制军营、传达命令和接近皇帝，其制度位置与私人关系相互加强。后来反刘瑾有现实贡献，却不能倒推其早期从未参与排挤外廷。人物变化应按时间分段，而不是用最终选择清洗此前责任。", [S304, S186], ["v143_nine_ministers_remonstrance"], ["m40_liujin", "houzhao"]),
            section("v143_zhangyong_s2", "献俘把军事成功变成直接奏事的窗口", "安化王事变后，张永以监军身份赴宁夏，实际抵达时仇钺已擒首领，他率兵安抚余部。杨一清劝其利用献俘接近武宗，直接陈述刘瑾不法。张永提前返京并在酒宴后奏事，促成逮捕。传记中的密谈与酒后反应经过文学整理，但结构可靠：军事差遣给予近侍合法离京和复命机会，胜利声望降低了指控风险，也让外臣意见绕过被刘瑾控制的文书链。", [S304, S198], ["v143_anhua_liujin"], ["m143_yangyiqing", "m40_liujin"]),
            section("v143_zhangyong_s3", "反刘瑾之后仍追求封赏并承担监军争议", "刘瑾死后，张永希望依宦官前例取得更高封赏，内阁以制度不合阻止；后来因库银案闲住，又重新督边。功劳与求利可以同时存在，不能因有功便把所有请求合理化，也不能因求赏否定其揭发结果。宦官监军常被写成文官制度的对立面，实际皇帝正借此监督将领；问题在于信息与问责高度依赖个人，成功时难复制，失败时又难由常规官署追究。", [S304, S16], ["v143_anhua_liujin", "v143_outer_four_armies"], ["m143_yangyiqing"]),
            section("v143_zhangyong_s4", "江西善后中既有争功，也有约束其他近侍", "宁王被王守仁擒获后，张永奉命南下，起初要求移交俘虏并试图配合皇帝亲征叙事。王守仁向他说明江西已经受创、再演战事会扩大风险，张永随后接收朱宸濠，催促张忠等离开，并在部分诬陷中王守仁。《明史》为张永辨称实无不法，带有评价倾向；较稳妥的结论是他参与军功控制，同时在近侍内部起到一定制约作用，两者不能互相抵消。", [S304, S117, "v40m2_ms195"], ["v143_ning_rebellion_local_cost"], ["m40_wangshouren", "m143_zhuchenhao"]),
            section("v143_zhangyong_s5", "武宗死后守九门，仍受新朝重新审查", "1521年武宗去世，张永督九门防变，并参与拘留江彬的安排。新帝即位后，言官把他与其他旧侍一并弹劾，先令闲住、后降职；多年后杨一清又为其前功申理。权力交接需要熟悉旧系统的人维持城防，也会在交接完成后重新追责。张永的轨迹说明宦官不是永远同盟的单一集团，外朝也会选择性合作。区分具体行为、阶段与证据，比把他列入忠宦或奸宦名单更可靠。", [S304, S190, S307], ["v143_succession_cleanup"], ["m143_yangtinghe", "m143_jiangbin"]),
        ]),
        article("m143_qianning", "钱宁：锦衣卫、私人进献与宗室关系怎样连成网络", "他的权力不只来自取悦皇帝，而是把诏狱、义子身份、艺术娱乐和宁王的京中通道连在一起。", [
            section("v143_qianning_s1", "从宦官家奴到掌锦衣卫", "钱宁幼年进入太监钱能家，借其姓氏和关系获得锦衣百户。正德初依附刘瑾，刘瑾倒台后又成功脱身，逐步掌南镇抚司和锦衣卫。武宗赐国姓、认作义子，使正式军职与拟制家族关系叠加。佞幸传用亲昵细节强调失序，可靠重点是钱宁能控制诏狱、校尉和上达渠道。制度风险不在出身低，而在侦缉、司法与私人信任缺少相互制衡。", [S307, S304], ["v143_anhua_liujin"], ["m40_liujin", "houzhao"]),
            section("v143_qianning_s2", "厂卫权力如何进入普通案件和官署", "钱宁掌锦衣卫后，能包庇部属、干预刑部案件，并与东厂形成‘厂、卫’并称。传记列举侵占财产和迫使官员屈从的案件，带有集中展示恶行的编排；具体责任仍应逐案核对。它揭示的制度机制较清楚：校尉可先拘人，诏狱可隔离常规审判，部院官为避免报复而改变决定。受害者不只是朝臣，家庭财产、仆役与案件证人也会被权力链牵连。", [S307], ["v143_nine_ministers_remonstrance"], ["m143_hanwen"]),
            section("v143_qianning_s3", "豹房娱乐也是人员与进献的筛选通道", "钱宁引入乐工、番僧等人，协助豹房和微行活动。娱乐本身不是罪证，问题是私人表演、礼物和亲密接触可以绕开官署推荐，成为职位、案件和宗室请求的交换空间。《明史》特别渲染秘戏与醉卧，具有传统道德叙事；不必复述猎奇细节。更值得追问的是谁能进入、谁替进献者传话、礼物如何登记，以及皇帝长时间不视朝时正式官员如何获得可靠指令。", [S307, S16], ["v143_imperial_shops_tours"], ["m143_jiangbin"]),
            section("v143_qianning_s4", "宁王恢复护卫为什么依赖京中中介", "朱宸濠为恢复护卫、安排世子和持续进献，借钱宁与乐工臧贤把物品和请求送到皇帝身边。钱宁既是锦衣卫首领，又充当宗室私人中介，使本应由礼部、兵部和宗人系统审查的事项被亲信关系包围。史书把他写成预谋依靠强藩自保，动机难以完全验证；护卫恢复、进献通道和对告警的遮蔽则有多条记录。关系网络削弱了风险信息进入中枢的机会。", [S307, S117], ["v143_ning_prince_network"], ["m143_zhuchenhao"]),
            section("v143_qianning_s5", "宁王起兵后，旧盟友迅速互相揭发", "1519年宁王起兵，武宗开始怀疑钱宁。钱宁试图切断与宁府使者的关系，江彬则向皇帝揭发其往来，钱宁被扣留并查抄，嘉靖初处死。查抄财物数字来自惩处叙事，不作现代财富换算，也不能自动证明每件都来自贪污。可以确认的是，私人网络缺少稳定规则：皇帝信任转移后，参与者会通过互相告发自保。钱宁的兴败说明个人接近能迅速聚权，也同样缺乏可预期的安全边界。", [S307, S117], ["v143_ning_prince_network", "v143_succession_cleanup"], ["m143_jiangbin", "m143_zhuchenhao"]),
        ]),
        article("m143_jiangbin", "江彬：边军进入宫廷以后，勇武如何变成组织问题", "战伤与骑射让他获得信任，真正改变政治的却是四镇军入京、巡幸供应和厂卫指挥集中。", [
            section("v143_jiangbin_s1", "从镇压内地武装到进入豹房", "正德六年北直隶等地起事，朝廷调边军入内地，江彬随军作战并负伤。武宗重视骑射和军事表现，钱宁引荐后，江彬凭伤痕与谈兵获得信任。传记也记其曾杀平民冒功，这类严重指控不能只因后来的恶名就免于核实；它至少提醒首功制度会诱发把平民算作敌人的风险。江彬的上升不是单纯会讨好，而是内地治安危机把边军能力带进皇帝视野。", [S307, S16], ["v143_uprising_mobilization"], ["m143_qianning", "houzhao"]),
            section("v143_jiangbin_s2", "外四家改变首都和边镇的指挥链", "江彬主张把辽东、宣府、大同、延绥军队留在北京，设置神威、敢勇等营，武宗亲自检阅并赋予江彬统领权。边军入京可提供训练与护卫，也意味着原镇兵力、家庭和粮饷被重新分配；驻军与城市居民之间还会发生住宿、交易和治安摩擦。佞幸传强调军士纵横，不能替代军籍统计，但指挥链绕过常规京营、依附皇帝与江彬，是可以确认的制度变化。", [S307, S190], ["v143_outer_four_armies"], ["m143_yangtinghe"]),
            section("v143_jiangbin_s3", "巡边有军事观察，也有无法拒绝的地方成本", "江彬推动武宗出居庸关、驻宣府，并继续巡大同、榆林和太原。皇帝确实在应州附近督军，不能把全部行动写成旅游；同时，行在需要边兵、驿递、粮草与住所，沿途居民没有拒绝供给的平等地位。传记对掠取妇女和娱乐多有渲染，具体个案需互证；但官员阻谏被捕、从者病于道路、皇店和行宫运作说明，个人军事兴趣已经转化为公共财政与人身代价。", [S307, S16], ["v143_imperial_shops_tours", "v2l_yingzhou"], ["houzhao", "m143_yangyiqing"]),
            section("v143_jiangbin_s4", "南征时厂卫、边军与军功叙事汇合", "宁王起兵后，江彬支持武宗亲征，又兼办东厂、锦衣事务并率边军南下。王守仁已经平乱，近侍仍试图重演献俘和重组军功，地方官民又面对追查、征发和诬陷。江彬并非单独决定南征，皇帝发布命令并持续前行；也不能把所有南方损害都归给一人。更重要的是军事指挥、侦缉司法和接近皇帝集中在同一网络，使地方难以通过正常复核纠正错误。", [S307, S117, S190], ["v143_south_tour_remonstrance", "v143_ning_rebellion_local_cost"], ["m40_wangshouren", "m143_zhuchenhao"]),
            section("v143_jiangbin_s5", "武宗死后，解除私人军权先于新帝进京", "武宗去世时，江彬仍掌威武营和边军，杨廷和先以遗命遣返部队、稳住其情绪，再经张太后与司礼监人员安排拘捕。江彬后被处死，查抄数字同样不应换算财富排名。权力交接的关键不是结局证明他必然谋反，而是一个依附私人信任的统兵者在皇帝去世后缺少清晰合法地位。朝廷必须控制城门、军营和信息，才有条件迎接朱厚熜。军队个人化的风险，由继承时的紧张最清楚地显现。", [S307, S190, S16], ["v143_succession_cleanup"], ["m143_yangtinghe", "m143_zhangyong", "houcong"]),
        ]),
        article("m143_zhuchenhao", "朱宸濠：宁王之乱不是突然发生的一天", "护卫、田产、京中中介和被阻断的告警长期累积，1519年的四十余日战事只是风险显形的最后阶段。", [
            section("v143_zhuchenhao_s1", "先分清明初宁王朱权与正德宁王朱宸濠", "朱宸濠是宁献王朱权后裔，生活在南昌宁府；他不是参与靖难的朱权，也不能把《神奇秘谱》等文化活动移到他名下。明代亲王有爵位、府属与庄田，军事护卫则受朝廷调整。宁府先前因罪削去护卫，朱宸濠在正德年间反复请求恢复。家族封号带来政治资源，却不等于所有宁王有相同经历。先厘清世系，才能理解这场叛乱是宗室制度中的具体事件。", [S117, S307], ["v143_ning_prince_network"], ["quan"]),
            section("v143_zhuchenhao_s2", "护卫恢复与田产扩张怎样制造地方摩擦", "朱宸濠借京中关系恢复部分护卫，又夺取官民田产、控制地方人员。护卫不仅是仪仗，还意味着可训练的武装、俸粮和指挥关系；庄田也不只是财富，而会改变居民土地、租税与诉讼去向。列传以王府侵夺组织材料，具体田亩与案件需地方档案互证。可以确认的是，军事资源和经济资源同步扩张，使巡抚面对的已不是普通宗室纠纷。监督若只处理单项奏请，就容易遗漏它们叠加后的风险。", [S117, S307], ["v143_ning_prince_network"], ["m143_qianning"]),
            section("v143_zhuchenhao_s3", "进献网络为什么会让预警到不了皇帝面前", "钱宁、臧贤等为宁府传递礼物和请求，朱宸濠又试图让世子进入太庙司香。巡抚孙燧上报异常，多次遭沿途拦截或在京中被遮蔽；其他官员也有人接受财物。史书说朝野皆知其必反，是事后回看式判断，不能假定所有人都掌握同样证据。但告警缺乏独立复核通道、被被告关系网控制，确实使风险升级。反腐不只查收礼，还应保护坏消息能越过利益网络。", [S117, S307], ["v143_ning_prince_network"], ["m143_qianning", "m143_jiangbin"]),
            section("v143_zhuchenhao_s4", "收回护卫的决定来得太晚，王府选择先发起兵", "1519年御史萧淮公开指控后，杨廷和主张派大臣宣谕、收回护卫和所夺田地。朱宸濠得知使者将至，在生日宴后扣押地方官，假称奉太后密旨起兵；孙燧、许逵拒绝合作被杀。这里既有长期谋划，也有朝廷措施触发的时间压力。不能把假诏当作真实授权，更不能因地方部分官员被迫或主动合作就把整个江西写成支持宁王。不同选择反映信息、武力和个人风险并不相同。", [S117, S190], ["v143_ning_rebellion_local_cost"], ["m143_yangtinghe"]),
            section("v143_zhuchenhao_s5", "四十余日平乱仍留下战后叙事和追责问题", "朱宸濠沿江攻安庆时，王守仁与伍文定等集结府县兵，先夺南昌，再截击返航军队并将其擒获。官修传称起兵四十三日，能说明行动迅速，兵力和伤亡则含号称与战功统计，不宜照抄为精确值。武宗南征和献俘争议又把地方胜利改造成宫廷军功叙事，近侍追查使居民继续受扰。平乱结局不能遮住起事前监督失败，也不能把所有责任都缩成朱宸濠个人野心。", [S117, "v40m2_ms195", S304], ["v143_ning_rebellion_local_cost", "v143_south_tour_remonstrance"], ["m40_wangshouren", "m143_zhangyong", "houzhao"]),
        ]),
    ]
    additions = {
        "v143_hanwen_s1": "还要区分军粮折放、市场平粜与无偿赈给：三者面对的人群不同，不能因米价暂降就推定最穷居民已经得到粮食。",
        "v143_hanwen_s2": "山陵工程还牵动石木、河运和沿途夫役；即使银两没有直接出自户部，实物与劳力仍可能由地方承担，不能把换一账户等同于节省。",
        "v143_hanwen_s3": "盐商取得引目后何时支盐、边仓实际收到多少粮草，与佃户能否拿到收租凭证，都比一纸禁令更能检验政策是否改变生活。",
        "v143_hanwen_s4": "韩文率百官集体行动扩大了压力，也把成败押在一次皇帝裁决上。缺少后续协商和申诉层级，使拒绝与服从之间几乎没有缓冲。",
        "v143_hanwen_s5": "他的家庭因罚米而受损，也提醒政治惩罚常通过财产和亲属扩散。官员个人承担风险值得记录，却不能遮住同案中较少留下姓名的吏员与家属。",
        "v143_yangtinghe_s1": "诰敕文字会把口头意向变成可传行命令，负责起草者因而不是纯粹文书人员；拒绝为威武大将军起草，也是一种对命令合法形式的抵抗。",
        "v143_yangtinghe_s2": "皇帝离京后，奏章还要经驿递送到行在，回复时间和身边过滤者都会改变信息。‘不报’既是态度，也是中枢与行在分离造成的治理延迟。",
        "v143_yangtinghe_s3": "北京留守还需处理边报、官员任免和日常钱粮，不能因史书只突出首辅便忽略六部与地方持续运作。维持常规本身就是制度劳动。",
        "v143_yangtinghe_s4": "张太后的认可为继承提供宫廷名分，宗室谱序提供法理，城门和军队控制提供现实保障；三者缺一，‘兄终弟及’都不会自动完成。",
        "v143_yangtinghe_s5": "被裁人员中既有冒滥者，也可能有按旧命服务的军士、工匠和杂役。清弊若不给安置与结算，同样会把制度转向的成本压给普通家庭。",
        "v143_yangyiqing_s1": "官茶运输还要经过产地征收、仓储和边地验收，途中损耗会影响交换比例。只看换得马匹数量，会忽略茶户与脚夫承担的成本。",
        "v143_yangyiqing_s2": "堡寨建成后仍要有人戍守、轮换和供粮，墙体也会受风沙与雨水破坏。一次拨款只能形成工程，不能自动形成可持续的防御能力。",
        "v143_yangyiqing_s3": "刘瑾案后所撤改的制度数量来自廷臣汇总，既包含恢复旧制，也可能取消原本有行政目的的措施。不能把所有变化按提出者身份一概判定。",
        "v143_yangyiqing_s4": "他能借张永进入中枢，后来也因钱宁、江彬的接近而离开。相同的私人渠道既可被用来纠偏，也会使政策缺少可预期的持续性。",
        "v143_yangyiqing_s5": "边防方案还应比较不修墙、增骑兵、互市或迁移堡寨的替代成本。传记保存他的主张，并不证明当时只有这一种合理选择。",
        "v143_zhangyong_s1": "神机营涉及火器、操练和京城防卫，掌营近侍拥有的不只是宫内影响。军事岗位使私人冲突可能直接影响首都的武力配置。",
        "v143_zhangyong_s2": "仇钺实际擒获安化王的功劳不能被监军复命吞没。区分前线平乱、善后安抚与中枢揭发，才能避免把三件事合成张永一人之功。",
        "v143_zhangyong_s3": "张永兄弟获封的安排显示恩赏仍可能通过亲属兑现。本人辞让更高封爵值得记录，却不能抹去家族已经从政治成功中获得的利益。",
        "v143_zhangyong_s4": "接收俘虏让皇帝一方控制献俘仪式，也使王守仁避免继续押解的风险。政治叙事和实际安全在这一交接中同时存在。",
        "v143_zhangyong_s5": "新朝对旧近侍的处理既是追责，也是在重建忠诚网络。后来恢复任用说明结论会随政治需要改变，不能把每次升降都直接视为司法事实。",
        "v143_qianning_s1": "所谓义子并非宗法上的皇子继承权，却能制造类似家人的称谓和礼遇。若把拟制亲属误作法定继承关系，就会误读他与宁王世子的谋划。",
        "v143_qianning_s2": "厂卫案件还会让被告无法接触常规审理、让主管官员担心自身被侦缉。程序不透明造成的寒蝉效应，比单个酷吏的性格更持久。",
        "v143_qianning_s3": "乐工和宗教人士也可能只是被征召的服务者，不能因进入豹房便统称为政治同谋。应把中介、受益者与被迫参与者分开。",
        "v143_qianning_s4": "宁府礼物进入北京后是否登记、由谁估值、请求是否交部议，都是监督节点。史料只保留部分结果，不能虚构一套完整秘密账簿。",
        "v143_qianning_s5": "钱宁试图灭口的记载属于严重案件叙述，应注明来源而不作细节扩写。其失势的制度事实是锦衣卫控制随皇帝一句话被撤回。",
        "v143_jiangbin_s1": "边军善战的名声来自长期边境训练，也不保证适合内地追剿。地形、补给与辨认居民身份不同，冒功风险正是在这种转换中上升。",
        "v143_jiangbin_s2": "边军长期离镇还会使军属分离，原驻地需要其他部队填补。首都看到的是精锐仪仗，边镇承担的空缺却不容易进入宫廷叙事。",
        "v143_jiangbin_s3": "应州战果数字长期存在争论，本文只确认交战、撤退与大规模叙赏，不由十六级首功推断全部伤亡，也不凭后世传奇夸大战果。",
        "v143_jiangbin_s4": "厂卫校尉随军后，军事嫌疑与普通司法更容易混合。被指为宁王党羽的人是否有证据、由谁审理，决定平叛会不会变成扩大牵连。",
        "v143_jiangbin_s5": "遣返边军还涉及路粮、欠饷和交还装备；诏令写‘散归’只是开始。若没有这些交接，解除一名统领仍可能留下成群失去供给的士兵。",
        "v143_zhuchenhao_s1": "宁藩世系本身可由宗谱与册封记录核对，人物性格则多由事后叛乱叙事倒写。先确认制度位置，可避免用结局解释他出生以来的一切。",
        "v143_zhuchenhao_s2": "王府田产可能来自赐予、购买、投献或侵夺，不同来源法律状态不同。把它们一概称为皇庄或全部视为合法，都无法说明具体诉讼。",
        "v143_zhuchenhao_s3": "孙燧持续上报也显示地方并非无人警觉。真正的缺口是信件会被截、京官可庇护，而朝廷缺少让多路报告交叉验证的机制。",
        "v143_zhuchenhao_s4": "被扣官员中有人拒绝、有人屈从，处境包括武力威胁与家属安全。战后追责应区分主动谋划、被迫任职和伺机逃离，不能只看名册。",
        "v143_zhuchenhao_s5": "安庆守城牵制宁王，为王守仁攻取南昌争取时间，也说明胜利来自多地协作。只突出一位名臣，会抹去守军、船工和传递情报者。",
    }
    for reading in readings:
        for item in reading["sections"]:
            item["text"] += additions[item["id"]]
        upsert(data["articles"], reading, key="person")

    # Connect the emperor overview to the newly inspectable people and mechanisms.
    emperor_article = next(item for item in data["articles"] if item["person"] == "houzhao")
    section_map = {item["id"]: item for item in emperor_article["sections"]}
    section_map["houzhao-2"]["people"] = ["m40_liujin", "m40_liujian", "m40_xieqian", "m40_lidongyang", "m42_mawensheng", "m143_hanwen", "m143_yangyiqing", "m143_zhangyong", "m143_qianning", "m143_jiangbin"]
    section_map["houzhao-2"]["events"] = ["v2l_liujin", "v40m2_liujin_power_1506", "v42m_chuanfeng", "v143_nine_ministers_remonstrance", "v143_anhua_liujin"]
    section_map["houzhao-3"]["people"] = ["m143_qianning", "m143_jiangbin", "m143_yangtinghe"]
    section_map["houzhao-3"]["events"] = ["v143_outer_four_armies", "v143_imperial_shops_tours"]
    section_map["houzhao-5"]["people"] = ["m40_wangshouren", "m143_zhuchenhao", "m143_yangtinghe", "m143_zhangyong", "m143_jiangbin"]
    section_map["houzhao-5"]["events"] = ["v2l_ningwang", "v143_south_tour_remonstrance", "v143_ning_rebellion_local_cost"]
    section_map["houzhao-6"]["people"] = ["houcong", "m143_yangtinghe", "m143_zhangyong", "m143_jiangbin"]
    section_map["houzhao-6"]["events"] = ["v143_succession_cleanup"]
    for source_id in [S186, S190, S198, S304, S307, S117]:
        if source_id not in emperor_article["sources"]:
            emperor_article["sources"].append(source_id)

    associations = [
        {"from": "m143_hanwen", "to": "m40_liujian", "role": "共同推动九卿与内阁反对武宗旧侍", "inverse": "以内阁程序支持其九卿伏阙", "period": "1506", "note": "两人政治目标接近，但户部国计与内阁决策责任并不相同。", "sources": [S186, S16]},
        {"from": "m143_yangyiqing", "to": "m143_zhangyong", "role": "在安化王善后中劝其直接揭发刘瑾", "inverse": "采纳其谋划并利用献俘机会揭发刘瑾", "period": "1510", "note": "官修史突出密谋细节；可确认的是外臣判断、近侍渠道和皇帝撤权共同起作用。", "sources": [S198, S304]},
        {"from": "m143_qianning", "to": "m143_zhuchenhao", "role": "为宁府护卫、世子与进献提供京中通道", "inverse": "借其接近皇帝并遮蔽部分告警", "period": "1507—1519", "note": "进献关系明确，双方是否有完整预定的共同谋反计划仍应谨慎。", "sources": [S307, S117]},
        {"from": "m143_qianning", "to": "m143_jiangbin", "role": "先引荐其接近武宗，后因争宠与宁王案互相倾轧", "inverse": "经其引荐进入豹房，后揭发其与宁府关系", "period": "1512—1519", "note": "私人联盟随皇帝信任转移而变化，不能当作稳定官署关系。", "sources": [S307]},
        {"from": "m143_jiangbin", "to": "m143_yangtinghe", "role": "掌边军与威武营，成为武宗身后必须先解除的军权", "inverse": "借遗命、太后和司礼监安排遣军并拘捕其人", "period": "1517—1521", "note": "解除军权是继承安全措施，不等于当时已经由法院证明江彬发动叛乱。", "sources": [S307, S190]},
        {"from": "m143_yangtinghe", "to": "m143_zhuchenhao", "role": "主张收护卫与所夺田产，后留守中枢处理平叛政务", "inverse": "朝廷监督与收权措施直接针对的宁藩首领", "period": "1519", "note": "收权决定触发时间压力，但叛乱责任不能转嫁给监督者。", "sources": [S190, S117]},
        {"from": "m143_zhangyong", "to": "m40_wangshouren", "role": "接收朱宸濠并约束部分南征近侍的战后追查", "inverse": "向其说明江西成本并移交宁王俘虏", "period": "1519—1520", "note": "二人既有军功叙事上的张力，也存在减少地方继续受扰的协作。", "sources": [S304, "v40m2_ms195"]},
        {"from": "m143_yangtinghe", "to": "houcong", "role": "依宗室伦序参与迎立并主持登极初期清理", "inverse": "由其与张太后、阁臣安排从兴王世子入继皇统", "period": "1521", "note": "迎立合作不等于随后大礼议中宗法立场一致。", "sources": [S190, S16]},
    ]
    for association in associations:
        upsert_association(data, association)

    data["version"] = 117
    data["reviewed"] = "2026-10-31"
    DATA.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    narration = json.loads(NARRATION.read_text(encoding="utf-8"))
    # The emperor prose itself is unchanged; only its related links were enriched,
    # so the existing section audio remains valid.
    changed = {reading["person"] for reading in readings}
    narration["entries"] = [entry for entry in narration["entries"] if entry["articleID"] not in changed]
    NARRATION.write_text(json.dumps(narration, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
